339	    /**
340	     * The maximum number of owners that may be created in a single business day. Owner
341	     * creation is rejected once this many owners already fall on the new owner's adjusted
342	     * business day {@code registrationDate}.
343	     */
344	    private static final int MAX_OWNERS_PER_DAY = 100;
