346	    /**
347	     * Rolls a date forward to the next business day: a Saturday or Sunday is moved forward
348	     * to the following Monday, while a weekday is returned unchanged.
349	     *
350	     * @param date the date to adjust
351	     * @return the same date if it is a weekday, otherwise the following Monday
352	     */
353	    private LocalDate toBusinessDay(LocalDate date) {
354	        DayOfWeek dayOfWeek = date.getDayOfWeek();
355	        if (dayOfWeek == DayOfWeek.SATURDAY) {
356	            return date.plusDays(2);
357	        }
358	        if (dayOfWeek == DayOfWeek.SUNDAY) {
359	            return date.plusDays(1);
360	        }
361	        return date;
362	    }
