467	    /**
468	     * Builds the membership number for a newly created owner, formatted
469	     * {@code '<customerCode>-M<YY>'} where {@code customerCode} is the owner's assigned
470	     * customer code and {@code YY} is the last two digits of the owner's registration
471	     * date year, zero-padded to two digits.
472	     *
473	     * @param customerCode     the owner's assigned customer code (e.g. {@code 'NSW-1A2B3C4D'})
474	     * @param registrationDate the owner's registration date
475	     * @return the assigned membership number (e.g. {@code 'NSW-1A2B3C4D-M26'})
476	     */
477	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
478	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
479	    }
