501	    /**
502	     * Canonical expansions applied to common street-type abbreviations during address
503	     * normalization. Keys and values are upper-cased so the lookup runs after the address
504	     * has itself been upper-cased.
505	     */
506	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
507	        "ST", "STREET",
508	        "RD", "ROAD",
509	        "AVE", "AVENUE");
510	
511	    /**
512	     * Normalizes an owner address for creation. Leading and trailing whitespace is trimmed,
513	     * every run of internal whitespace is collapsed to a single space, the result is
514	     * upper-cased and common street-type abbreviations are expanded ({@code ST -> STREET},
515	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). An abbreviation is recognized as a whole
516	     * token, optionally carrying a single trailing full stop (so both {@code 'St'} and
517	     * {@code 'St.'} become {@code 'STREET'}). The normalized value is what gets stored,
518	     * returned and compared for household duplicates; an address that is blank once
519	     * normalized fails the required-field check.
520	     *
521	     * @param address the raw address value supplied by the client
522	     * @return the normalized address (empty string when {@code address} is null or blank)
523	     */
524	    /**
525	     * Normalizes the address an owner supplies, preferring the structured form, and stores the
526	     * normalized structured lines on the owner. When a non-blank {@code addressLine1} is present
527	     * the structured fields are used: {@code addressLine1} (and {@code addressLine2}, when
528	     * present) are {@link #normalizeAddress normalized} and set on the owner, and the composed
529	     * address returned is the normalized {@code addressLine1} with a single space and the
530	     * normalized {@code addressLine2} appended when {@code addressLine2} is present. Otherwise
531	     * the flat {@code address} is normalized and returned, and the structured lines are left
532	     * unset. The returned value becomes the owner's stored {@code address}, read by everything
533	     * downstream (household hash, postcode validation and locality); an owner that supplies
534	     * neither form yields an empty string, failing the required-address check.
535	     *
536	     * @param owner          the owner being created, whose structured address lines are set here
537	     * @param ownerFieldsDto the submitted owner fields
538	     * @return the composed, normalized address (empty string when no address form is supplied)
539	     */
540	    private static String applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
541	        String addressLine1 = ownerFieldsDto.getAddressLine1();
542	        if (addressLine1 != null && !addressLine1.isBlank()) {
543	            String normalizedLine1 = normalizeAddress(addressLine1);
544	            owner.setAddressLine1(normalizedLine1);
545	            String addressLine2 = ownerFieldsDto.getAddressLine2();
546	            if (addressLine2 != null && !addressLine2.isBlank()) {
547	                String normalizedLine2 = normalizeAddress(addressLine2);
548	                owner.setAddressLine2(normalizedLine2);
549	                return normalizedLine1 + " " + normalizedLine2;
550	            }
551	            owner.setAddressLine2(null);
552	            return normalizedLine1;
553	        }
554	        owner.setAddressLine1(null);
555	        owner.setAddressLine2(null);
556	        return normalizeAddress(ownerFieldsDto.getAddress());
557	    }
558	
559	    private static String normalizeAddress(String address) {
560	        if (address == null) {
561	            return "";
562	        }
563	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
564	        if (collapsed.isEmpty()) {
565	            return "";
566	        }
567	        StringBuilder normalized = new StringBuilder(collapsed.length());
568	        for (String token : collapsed.split(" ")) {
569	            String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
570	            String expanded = ADDRESS_ABBREVIATIONS.get(core);
571	            if (normalized.length() > 0) {
572	                normalized.append(' ');
573	            }
574	            normalized.append(expanded != null ? expanded : token);
575	        }
576	        return normalized.toString();
577	    }
578	
579	    /**
580	     * Normalizes a last name or address for household-duplicate comparison: leading and
581	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
582	     * single space and the result is lower-cased. Two owners are considered to share a
583	     * household when both their last names and addresses produce the same key.
584	     *
585	     * @param value the raw last name or address value
586	     * @return the normalized comparison key (empty string when {@code value} is null)
587	     */
588	    private static String householdKey(String value) {
589	        if (value == null) {
590	            return "";
591	        }
592	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
593	    }
594	
595	    /**
596	     * Derives the stable shared household identifier for the given normalized last name key
597	     * and postcode. The identifier is deterministic — the same household (same
598	     * {@link #householdKey normalized} last name and postcode) always maps to the same
599	     * value — so every owner in a household is assigned an identical id. It is the
600	     * upper-cased first twelve hex characters of the SHA-256 digest of {@code
601	     * '<lastNameKey>|<postcode>'}.
602	     *
603	     * @param lastNameKey the normalized last name key
604	     * @param postcode    the owner's postcode
605	     * @return the shared household identifier
606	     */
607	    private static String householdId(String lastNameKey, String postcode) {
608	        String source = lastNameKey + "|" + postcode;
609	        try {
610	            byte[] digest = MessageDigest.getInstance("SHA-256")
611	                .digest(source.getBytes(StandardCharsets.UTF_8));
612	            StringBuilder hex = new StringBuilder(digest.length * 2);
613	            for (byte b : digest) {
614	                hex.append(String.format("%02x", b));
615	            }
616	            return hex.substring(0, 12).toUpperCase();
617	        } catch (NoSuchAlgorithmException e) {
618	            throw new IllegalStateException("SHA-256 not available", e);
619	        }
620	    }
621	
622	    /**
623	     * Computes the deterministic {@link #householdId household id} an existing owner belongs to,
624	     * derived from its {@link #householdKey normalized} last name and its postcode. Returns
625	     * {@code null} when the owner has no postcode (such an owner has no household), so it never
626	     * collides with a computed household id.
627	     *
628	     * @param owner the existing owner
629	     * @return the owner's household id, or {@code null} when it has no postcode
630	     */
631	    private static String computeHouseholdId(Owner owner) {
632	        if (owner.getPostcode() == null) {
633	            return null;
634	        }
635	        return householdId(householdKey(owner.getLastName()), owner.getPostcode());
636	    }
637	
638	    /**
639	     * Populates an owner's {@code membershipPoints} and {@code membershipLevel} on the given
640	     * dto, sizing the owner's household from all owners so the household-of-three-or-more
641	     * factor is scored correctly. Use {@link #applyMembership(OwnerDto, Owner, Map)} instead
642	     * when mapping a collection to size every household from a single scan.
643	     *
644	     * @param ownerDto the dto to populate
645	     * @param owner    the owner being mapped
646	     */
647	    private void applyMembership(OwnerDto ownerDto, Owner owner) {
648	        applyMembership(ownerDto, owner, householdSizes());
649	    }
650	
651	    /**
652	     * Populates an owner's {@code membershipPoints} and {@code membershipLevel} on the given
653	     * dto using a pre-computed map of household id to member count.
654	     *
655	     * @param ownerDto       the dto to populate
656	     * @param owner          the owner being mapped
657	     * @param householdSizes household id to member count, as returned by {@link #householdSizes()}
658	     */
659	    private void applyMembership(OwnerDto ownerDto, Owner owner, Map<String, Integer> householdSizes) {
660	        int householdSize = owner.getHouseholdId() == null ? 1
661	            : householdSizes.getOrDefault(owner.getHouseholdId(), 1);
662	        int points = MembershipPoints.points(owner, householdSize);
663	        ownerDto.setMembershipPoints(points);
664	        ownerDto.setMembershipLevel(MembershipPoints.level(points));
665	    }
666	
667	    /**
668	     * Counts how many owners belong to each household, keyed by household id. Owners without a
669	     * household id (no postcode) are excluded — such an owner is its own single-member household.
670	     *
671	     * @return a map from household id to the number of owners sharing it
672	     */
673	    private Map<String, Integer> householdSizes() {
674	        Map<String, Integer> sizes = new java.util.HashMap<>();
675	        for (Owner existing : this.clinicService.findAllOwners()) {
676	            String householdId = existing.getHouseholdId();
677	            if (householdId != null) {
678	                sizes.merge(householdId, 1, Integer::sum);
679	            }
680	        }
681	        return sizes;
682	    }
683	
684	    /**
685	     * Applies soft-match (possible-duplicate) detection to a new owner that has already
686	     * cleared hard {@code identityKey} duplicate rejection. The owner is flagged as a
687	     * possible duplicate when an existing owner shares its last name (compared
688	     * case-insensitively with collapsed whitespace) and its postcode while having a
689	     * different normalized telephone; {@code possibleDuplicateOf} is then set to that
690	     * existing owner's id. When several existing owners match, the one with the lowest id
691	     * is chosen so the result is deterministic. When no such owner exists — or the new
692	     * owner has no postcode to compare — {@code possibleDuplicate} is set to {@code false}
693	     * and no matching id is recorded.
694	     *
695	     * @param owner the new owner, already normalized (E.164 telephone, validated postcode)
696	     */
697	    private void applyPossibleDuplicate(Owner owner) {
698	        owner.setPossibleDuplicate(false);
699	        if (owner.getPostcode() == null) {
700	            return;
701	        }
702	        String lastNameKey = householdKey(owner.getLastName());
703	        Owner match = null;
704	        for (Owner existing : this.clinicService.findAllOwners()) {
705	            if (lastNameKey.equals(householdKey(existing.getLastName()))
706	                && owner.getPostcode().equals(existing.getPostcode())
707	                && !owner.getTelephone().equals(toE164(existing.getTelephone()))) {
708	                if (match == null || (existing.getId() != null
709	                    && existing.getId() < match.getId())) {
710	                    match = existing;
711	                }
712	            }
713	        }
714	        if (match != null) {
715	            owner.setPossibleDuplicate(true);
716	            owner.setPossibleDuplicateOf(match.getId());
717	        }
718	    }
719	
720	    /**
721	     * Builds the derived duplicate-detection identity key from an owner's normalized
722	     * telephone, email and household id, formatted {@code
723	     * '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. Two owners are
724	     * duplicates only when their whole identity keys are equal; because the telephone is
725	     * part of the key, members of the same household with different telephones produce
726	     * different keys and are both allowed.
727	     *
728	     * @param normalizedTelephone the E.164 telephone (may be {@code null})
729	     * @param email               the normalized (lower-cased) email, or {@code null} when absent
730	     * @param householdId         the shared household id, or {@code null} when the owner is not in a household
731	     * @return the identity key string
732	     */
733	    private static String identityKey(String normalizedTelephone, String email, String householdId) {
734	        return (normalizedTelephone == null ? "" : normalizedTelephone)
735	            + "|" + (email == null ? "" : email)
736	            + "|" + (householdId == null ? "" : householdId);
737	    }
738	
739	    /**
740	     * Normalizes an existing owner's stored email for identity-key comparison: trimmed and
741	     * lower-cased, mirroring {@link #normalizeEmail} without re-validating syntax. Returns
742	     * {@code null} when the owner has no email.
743	     *
744	     * @param email the existing owner's stored email (may be {@code null})
745	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is null
746	     */
747	    private static String emailForKey(String email) {
748	        return email == null ? null : email.trim().toLowerCase();
749	    }
750	
751	    /**
752	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
753	     * and brackets are stripped. When the number already carries a leading {@code '+'}
754	     * and country code these are kept; a number written in national trunk form (a leading
755	     * {@code '0'}) is treated as Australian, so the {@code '0'} is dropped and country code
756	     * {@code '+61'} prepended; any other bare number is treated as a NANP number and country
757	     * code {@code '+1'} is prepended. The resulting number must have between 8 and 15 digits
758	     * after the {@code '+'}, and its national-number length must be valid for the detected
759	     * country code (see {@link #hasValidNationalLength}).
760	     *
761	     * @param telephone the raw telephone value supplied by the client
762	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
763	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
764	     */
765	    private static String toE164(String telephone) {
766	        if (telephone == null) {
767	            return null;
768	        }
769	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
770	        String digits;
771	        if (cleaned.startsWith("+")) {
772	            digits = cleaned.substring(1);
773	        } else if (cleaned.startsWith("0")) {
774	            digits = "61" + cleaned.substring(1);
775	        } else {
776	            digits = "1" + cleaned;
777	        }
778	        if (!digits.matches("[0-9]{8,15}")) {
779	            return null;
780	        }
781	        if (!hasValidNationalLength(digits)) {
782	            return null;
783	        }
784	        return "+" + digits;
785	    }
786	
787	    /**
788	     * Validates the national-number length of an E.164 digit string against its country
789	     * code: Australia ({@code +61}) requires exactly 9 national digits and the NANP
790	     * ({@code +1}) requires exactly 10. Numbers under any other country code are not
791	     * length-checked here — only the general 8-to-15-digit E.164 bound applies to them.
792	     *
793	     * @param digits the E.164 digits (without the leading {@code '+'})
794	     * @return {@code true} when the national-number length is valid for the country code
795	     */
796	    private static boolean hasValidNationalLength(String digits) {
797	        if (digits.startsWith("61")) {
798	            return digits.length() - 2 == 9;
799	        }
800	        if (digits.startsWith("1")) {
801	            return digits.length() - 1 == 10;
802	        }
803	        return true;
804	    }
805	
806	    /**
807	     * Inclusive 4-digit postcode ranges permitted for each canonical region: NSW 2000-2099,
808	     * VIC 3000-3099 and QLD 4000-4099. A region absent from this table (e.g. the {@code
809	     * "UNKNOWN"} derived for a city with no known region) imposes no range restriction.
810	     */
811	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
812	        "NSW", new int[] {2000, 2099},
813	        "VIC", new int[] {3000, 3099},
814	        "QLD", new int[] {4000, 4099});
815	
816	    /**
817	     * Validates an owner's postcode for creation. A postcode is only ever validated when
818	     * present (an absent postcode is optional and accepted). When present it must be exactly
819	     * four digits and, for a city whose {@link OwnerLocality#forCity region} has a known
820	     * postcode range, must fall inside that inclusive range (NSW 2000-2099, VIC 3000-3099,
821	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
822	     *
823	     * @param postcode the supplied postcode (never {@code null} here)
824	     * @param city     the owner's city, used to derive the region
825	     * @return {@code true} when the postcode is valid for the city, {@code false} otherwise
826	     *         (signalling a 400 Bad Request)
827	     */
828	    private static boolean isValidPostcode(String postcode, String city) {
829	        if (!postcode.matches("[0-9]{4}")) {
830	            return false;
831	        }
832	        int[] range = REGION_POSTCODES.get(
833	            org.springframework.samples.petclinic.mapper.OwnerLocality.forCity(city));
834	        if (range == null) {
835	            return true;
836	        }
837	        int value = Integer.parseInt(postcode);
838	        return value >= range[0] && value <= range[1];
839	    }
840	
841	    /**
842	     * Disposable email domains that are not accepted for owner creation. An owner whose
843	     * email domain (compared case-insensitively) is in this set is rejected with a 400
844	     * Bad Request.
845	     */
846	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
847	        "mailinator.com", "tempmail.com", "guerrillamail.com");
848	
849	    /**
850	     * Normalizes an owner email for creation. A present email must be a syntactically
851	     * valid address whose domain is not on the disposable-domain blocklist ({@link
852	     * #DISPOSABLE_EMAIL_DOMAINS}); the returned value is lower-cased.
853	     *
854	     * @param email the raw email value supplied by the client (never {@code null} here)
855	     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
856	     *         address or its domain is a disposable domain (signalling a 400 Bad Request)
857	     */
858	    private static String normalizeEmail(String email) {
859	        String trimmed = email.trim();
860	        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
861	            return null;
862	        }
863	        String normalized = trimmed.toLowerCase();
864	        String domain = normalized.substring(normalized.indexOf('@') + 1);
865	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
866	            return null;
867	        }
868	        return normalized;
869	    }
870	}
